const toast=document.querySelector('#toast');let timer;function say(message){toast.textContent=message;toast.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>toast.classList.remove('show'),3600)}document.querySelector('#searchForm').addEventListener('submit',e=>{e.preventDefault();say('Discovery is using illustrative Phase 1 data; live availability arrives in Phase 4.')});document.querySelectorAll('[data-toast]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();say(el.dataset.toast)}));document.querySelectorAll('.filters button').forEach(b=>b.addEventListener('click',()=>{document.querySelector('.filters .active').classList.remove('active');b.classList.add('active');say(`${b.textContent} filters are a visual prototype in Phase 1.`)}));document.querySelectorAll('.heart').forEach(b=>b.addEventListener('click',()=>{b.textContent=b.textContent==='♡'?'♥':'♡';say('Saving vehicles will be available after secure accounts are introduced.')}));const dialog=document.querySelector('#vehicleDialog');document.querySelectorAll('.details-button').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#dialogName').textContent=button.dataset.vehicle;document.querySelector('#dialogMeta').textContent=`${button.dataset.location} · Prototype vehicle detail`;document.querySelector('#dialogMode').textContent=button.dataset.mode;dialog.showModal()}));document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
